      const Resolution = Extent.map((Length2) => Math.max(MinimumVolumeTexels, Math.min(MaximumVolumeTexels, Math.ceil((Length2 + 2 * Margin()) / Voxel))));
      const Centre = [0, 1, 2].map((Axis) => 0.5 * (Set2.LocalMinimum[Axis] + Set2.LocalMaximum[Axis]));
      const Minimum = [0, 1, 2].map((Axis) => Centre[Axis] - 0.5 * Resolution[Axis] * Voxel);
      const Volume = { FacetSet: SetIndex, VoxelExtent: Voxel, Resolution, Minimum, TexelOrigin: [0, 0, Depth] };
