function ConstructEntities(Host2) {
  const S = Host2.Settings;
  const Entities = [
    {
      Id: "render",
      Group: "Render",
      Name: "Render settings",
      Type: "Renderer",
      Glyph: "Monitor",
      Colour: Accent.Render,
      Description: "RTX ReSTIR Path Tracer, resolution, reflections & debug views",
      Meta: () => `${S.RayTracing ? "RTX \xB7 PT" : "GTX \xB7 SDF"} \xB7 ${Host2.GradeName}`,
      State: () => "live",
      Build: (C, B) => BuildRender(Host2, C, B),
      Switches: () => [
        Feature("Raytracing", "Zap", S, "RayTracing"),
        Feature("Indirect", "Sparkles", S, "Indirect"),
        Feature("Reflections", "Aperture", S, "Reflection"),
        Feature("Denoiser", "Layers", S, "VarianceKernel"),
        Feature("TAA", "Scan", S, "Antialias")
      ]
    },
    {
      Id: "field",
      Group: "Render",
      Name: "BVH & distance field",
      Type: "Acceleration structures",
      Glyph: "GridLattice",
      Colour: Accent.Render,
      Description: "Two-level BVH (TLAS + BLAS) & toroidal SDF cascades",
      Meta: () => S.RayTracing && Host2.RayTracing ? `${Host2.RayTracing.ActiveInstances} TLAS` : `${Host2.Grade.ClipResolution}\xB3`,
      State: () => S.FreezeDistance ? "warm" : "live",
      Build: (C, B) => BuildField(Host2, C, B)
    },
    {
      Id: "cards",
      Group: "Render",
      Name: "Surface cache",
      Type: "Surface cards",
      Glyph: "LayoutGrid",
      Colour: Accent.Render,
      Description: "Card radiosity & relighting budget",
      Meta: () => `${Host2.Cards.Cards.length}`,
      State: () => "live",
      Build: (C, B) => BuildCards(Host2, C, B)
    },
    {
      Id: "sun",
      Group: "Environment",
      Name: "Sun & sky",
      Type: "Directional light",
      Glyph: "Sun",
      Colour: Accent.Environment,
      Description: "Light, direction & atmosphere",
      Meta: () => `${S.SunElevation.toFixed(0)}\xB0`,
      State: () => S.SunElevation > 0 ? "live" : "warm",
      Build: (C, B) => BuildSun(Host2, C, B),
      Switches: () => [Feature("Shadows", "Sun", S, "DirectShadow"), Feature("Auto exposure", "Aperture", S, "AutoExposure")]
    },
    {
      Id: "vehicle",
      Group: "Vehicle",
      Name: "ControlVehicle",
      Type: "Vehicle",
      Glyph: "Car",
      Colour: Accent.Vehicle,
      Description: "Telemetry, burnout, tyres & camera",
      Meta: () => `${Math.abs(Host2.Vehicle.QueryTelemetry().Speed * 3.6).toFixed(0)} km/h`,
      State: () => Host2.Vehicle.Burnout ? "warm" : "live",
      Build: (C, B) => BuildVehicle(Host2, C, B),
      Switches: () => [
        Feature("Line lock", "Flame", S, "LineLock"),
        Feature("Thermal grip", "Thermometer", S, "ThermalGrip"),
        Feature("Tyre marks", "CircleDot", S, "TyreMarks"),
        Feature("Sparks", "Zap", S, "Sparks")
      ]
    },
    {
      Id: "cabin",
      Group: "Vehicle",
      Name: "Cabin \xB7 HMI",
      Type: "Interior",
      Glyph: "Monitor",
      Colour: Accent.Vehicle,
      Parent: "vehicle",
      Description: "Tablet & cluster, mirrors, glass, interior cameras",
      Meta: () => S.CameraMode,
      State: () => Host2.Cabin && Host2.Cabin.Screen ? "live" : "warm",
      Build: (C, B) => BuildCabin(Host2, C, B),
      Switches: () => [
        {
          Name: "See-through glass",
          Glyph: "Eye",
          Read: () => Host2.Cabin.Settings.SeeThroughGlass,
          Write: (On) => {
            Host2.Cabin.Settings.SeeThroughGlass = On;
          }
        },
        { Name: "Screens", Glyph: "Monitor", Read: () => Host2.Cabin.Settings.Screens, Write: (On) => {
          Host2.Cabin.Settings.Screens = On;
        } }
      ]
    },
    {
      Id: "marks",
      Group: "Vehicle",
      Name: "Tyre marks",
      Type: "Rubber deposit",
      Glyph: "CircleDot",
      Colour: Accent.Vehicle,
      Parent: "vehicle",
      Description: "Rubber laid by sliding work",
      Meta: () => `${Host2.Marks.Metrics.LaidMetres.toFixed(0)} m`,
      State: () => S.TyreMarks ? "live" : "",
      Build: (C, B) => BuildMarks(Host2, C, B),
      Toggle: { Read: () => S.TyreMarks, Write: (On) => {
        S.TyreMarks = On;
      } }
    },
    {
      Id: "gas",
      Group: "Effects",
      Name: "Smoke & fire",
      Type: "Gas domain",
      Glyph: "Flame",
      Colour: Accent.Effects,
      Description: "Eulerian smoke \xB7 combustion \xB7 tyre sources",
      Meta: () => Host2.Smoke.Resident ? "resident" : "idle",
      State: () => Host2.Smoke.Resident ? "live" : "",
      Build: (C, B) => BuildGas(Host2, C, B),
      Toggle: { Read: () => S.SmokeEnabled, Write: (On) => {
        S.SmokeEnabled = On;
      } },
      Switches: () => [
        Feature("Smoke", "CloudFog", S, "SmokeEnabled"),
        { Name: "Ignition", Glyph: "Flame", Read: () => S.IgnitionMode !== 2, Write: (On) => {
          S.IgnitionMode = On ? 0 : 2;
        } },
        { Name: "Test plume", Glyph: "Wind", Read: () => S.TestPlume > 0, Write: (On) => {
          S.TestPlume = On ? 1 : 0;
        } },
        Feature("Line lock", "Gauge", S, "LineLock")
      ]
    },
    {
      Id: "fracture",
      Group: "Destruction",
      Name: "Fracture",
      Type: "Breakable props",
      Glyph: "Hammer",
      Colour: Accent.Destruction,
      Description: "Energy-limited fracture \xB7 fragment bodies",
      Meta: () => `${Host2.Fracture.Props.filter((Prop) => Prop.State === "intact").length}/${Host2.Fracture.Props.length}`,
      State: () => Host2.Fracture.Metrics.ActiveFragments > 0 ? "warm" : "live",
      Build: (C, B) => BuildFractureGlobal(Host2, C, B),
      Toggle: { Read: () => Host2.Fracture.Settings.Enabled, Write: (On) => {
        Host2.Fracture.Settings.Enabled = On;
      } },
      Switches: () => [Feature("Breakable", "Hammer", Host2.Fracture.Settings, "Enabled"), Feature("Respawn", "RotateCcw", Host2.Fracture.Settings, "Respawn")]
    }
  ];
  for (const Prop of Host2.Fracture.Props) {
    const Material = () => FractureMaterials[Prop.Recipe.Material];
    Entities.push({
      Id: `prop-${Prop.Index}`,
      Group: "Destruction",
      Name: Prop.Definition.Name,
      Type: "Breakable prop",
      Parent: "fracture",
      Glyph: Prop.Definition.Shape.Kind === "prism" ? "CircleDot" : Prop.Recipe.Material.includes("glass") || Prop.Recipe.Material === "tempered" ? "Gem" : "Box",
      Colour: Accent.Destruction,
      Description: "Per-object geometry \xB7 Fracture editor",
      Meta: () => Prop.State === "intact" ? Material().Label : `${Prop.Pieces.length} pcs`,
      State: () => Prop.State === "intact" ? "live" : "warm",
      Toggle: { Read: () => Prop.Recipe.Enabled, Write: (On) => {
        Prop.Recipe.Enabled = On;
      } },
      Build: (C, B) => BuildProp(Host2, Prop, C, B),
      Switches: () => [
        Feature("Breakable", "Hammer", Prop.Recipe, "Enabled"),
        {
          Name: "Dynamic",
          Glyph: "Zap",
          Read: () => Prop.Recipe.Mode === FractureModes.Dynamic,
          Write: (On) => Host2.Fracture.AssignRecipe(Prop, { Mode: On ? FractureModes.Dynamic : FractureModes.Baked })
        }
      ]
    });
  }
  Entities.push(
    {
      Id: "derez",
      Group: "Effects",
      Name: "Derez \xB7 VFX",
      Type: "Particle effect",
      Glyph: "Sparkles",
      Colour: Accent.Effects,
      Description: "Particle Editor presets \xB7 recovery & respawn",
      Meta: () => Host2.Effects.Settings.Preset,
      State: () => Host2.Recovery.Busy || Host2.Effects.Metrics.Live > 0 ? "warm" : "live",
      Build: (C, B) => BuildDerez(Host2, C, B),
      Switches: () => [Feature("Auto recovery", "Shield", Host2.Recovery.Settings, "Enabled")]
    },
    {
      Id: "training",
      Group: "Level",
      Name: "Training arena",
      Type: "Drills",
      Glyph: "Flag",
      Colour: Accent.Level,
      Description: "Ten timed stations \xB7 best times",
      Meta: () => Host2.Training.Active ? Host2.Training.Active.Drill.Name : `${TrainingDrills.length} drills`,
      State: () => Host2.Training.Active && Host2.Training.Active.Phase === "running" ? "warm" : "live",
      Build: (C, B) => BuildTraining(Host2, C, B)
    },
    {
      Id: "cones",
      Group: "Level",
      Name: "Cones",
      Type: "Rigid bodies",
      Glyph: "TrafficCone",
      Colour: Accent.Level,
      Parent: "training",
      Description: "Knockable cones \xB7 rez back on reset",
      Meta: () => `${Host2.Cones.Cones.length}`,
      State: () => Host2.Cones.Metrics.Moving > 0 ? "warm" : "live",
      Build: (C, B) => BuildCones(Host2, C, B)
    },
    {
      Id: "level",
      Group: "Level",
      Name: "Proving grounds",
      Type: "Level",
      Glyph: "Map",
      Colour: Accent.Level,
      Description: "Zones, teleports & scene budget",
      Meta: () => `${LevelZones.length} zones`,
      State: () => "live",
      Build: (C, B) => BuildLevel(Host2, C, B)
    },
    {
      Id: "stress",
      Group: "Level",
      Name: "Stress test",
      Type: "Object pool",
      Glyph: "Boxes",
      Colour: Accent.Level,
      Description: "Pre-built pool \xB7 union, cards & draws under load",
      Meta: () => `${Host2.Stress.QueryActive()}`,
      State: () => Host2.Stress.QueryActive() > 0 ? "warm" : "",
      Build: (C, B) => BuildStress(Host2, C, B)
    }
  );
  return Entities;
}
function Feature(Name, Glyph, Target, Key) {
  return { Name, Glyph, Read: () => !!Target[Key], Write: (On) => {
    Target[Key] = On;
  } };
}
function Slider(C, Parent, Target, Key, Label, Minimum, Maximum, Step2, Unit = "", Digits = 2, Labels = null, OnInput = null) {
  return C.Slider(Parent, Target, Key, { Label, Minimum, Maximum, Step: Step2, Unit, Digits, Labels, OnInput });
}
function GasSlider(C, Parent, Gas, Key, Labels = null) {
  const Entry = GasParameterCatalogue[Key];
  const Digits = Entry.Step >= 1 ? 0 : Entry.Step >= 0.1 ? 1 : Entry.Step >= 0.01 ? 2 : 3;
  return C.Slider(Parent, Gas, Key, {
    Label: Entry.Label,
    Minimum: Entry.Minimum,
    Maximum: Entry.Maximum,
    Step: Entry.Step,
    Unit: Entry.Unit,
    Digits,
    Labels
  });
}
function BuildRender(Host2, C, Body2) {
  const S = Host2.Settings;
  const Arch = C.Card(Body2, "RTX \xB7 ReSTIR Path Tracer", "Zap", { Accent: Accent.Render, Index: 1 });
  C.Metric(
    Arch,
    () => S.RayTracing ? `${S.MaxBounces}B GI \xB7 ${S.ReflectionBounces}B Refl \xB7 M=${S.InitialCandidates}` : "GTX SDF GI",
    "",
    0,
    () => [S.RayTracing ? "RTX raytracing" : "GTX distance field", "live"]
  );
  C.Muted(Arch, "Two-level BVH (TLAS over scene occupants + Binned-SAH BLAS per mesh) with multi-bounce BSDF importance sampling, RIS Next-Event Estimation, MIS, and Russian Roulette.");
  C.Segmented(Arch, S, "RayTracing", [["RTX \xB7 ReSTIR Path Tracer", true], ["GTX \xB7 Distance-Field GI", false]], { Label: "Renderer architecture" });
  Slider(C, Arch, S, "MaxBounces", "GI path bounces", 1, 4, 1, "", 0, ["1 bounce", "4 bounces"]);
  Slider(C, Arch, S, "ReflectionBounces", "Reflection bounces", 1, 4, 1, "", 0, ["1 bounce", "4 bounces"]);
  Slider(C, Arch, S, "InitialCandidates", "Initial RIS path candidates", 1, 4, 1, "", 0, ["Fast", "Low variance"]);
  C.Switch(Arch, S, "RayTracedShadows", { Label: "Ray-traced direct & IES shadows", Detail: "Exact BVH visibility for sun cone, street lamps & headlights" });
  C.Switch(Arch, S, "RayTracedReflections", { Label: "Ray-traced multi-bounce reflections", Detail: "GGX VNDF & mirror BVH reflections across car paint, glass & wet asphalt" });
  C.Switch(Arch, S, "MultiBounceNEE", { Label: "Multi-bounce NEE + RIS", Detail: "Direct sun, fire & IES light sampling at secondary path vertices" });
  C.Switch(Arch, S, "RussianRoulette", { Label: "Russian roulette termination", Detail: "Throughput-weighted unbiased path continuation" });
  C.Switch(Arch, S, "FireflyFilter", { Label: "Firefly & boiling suppression", Detail: "Jacobian & luminance outlier clamp" });
  const Refl = C.Card(Body2, "Ray-traced reflections", "Aperture", { Accent: Accent.Render, Index: 2 });
  C.Metric(
    Refl,
    () => S.Reflection ? S.RayTracing && S.RayTracedReflections ? `RTX \xB7 ${S.ReflectionBounces} bounce${S.ReflectionBounces > 1 ? "s" : ""}` : "GTX \xB7 SDF" : "Off",
    "",
    0,
    () => [`rough \u2264 ${(S.ReflectionRoughness ?? 0.8).toFixed(2)}`, S.Reflection ? "live" : "warm"]
  );
  C.Muted(Refl, "Multi-bounce GGX VNDF glossy and mirror reflections traced against the Two-Level BVH with direct NEE, surface-card GI, and SVGF spatio-temporal reconstruction.");
  C.Switch(Refl, S, "Reflection", { Label: "Enable glossy & mirror reflections", Detail: "Screen-space reflection target + exterior mirror glass" });
  C.Switch(Refl, S, "RayTracedReflections", { Label: "Use RTX BVH reflection rays", Detail: "Exact triangle hits instead of SDF sphere-tracing" });
  Slider(C, Refl, S, "ReflectionBounces", "Reflection bounces", 1, 4, 1, "", 0, ["Single bounce", "4 bounces"]);
  Slider(C, Refl, S, "ReflectionScale", "Reflection intensity", 0, 3, 0.05, "\xD7", 2);
  Slider(C, Refl, S, "ReflectionRoughness", "Roughness cutoff", 0.15, 1, 0.05, "", 2, ["Mirror only", "All surfaces"]);
  const Quality = C.Card(Body2, "Resolution & quality", "Monitor", { Accent: Accent.Render, Index: 3 });
  C.Metric(
    Quality,
    () => Host2.ScreenExtent ? `${Host2.ScreenExtent[0]}\xD7${Host2.ScreenExtent[1]}` : "\u2013",
    "px",
    0,
    () => [`trace ${Host2.TraceExtent ? Host2.TraceExtent.join("\xD7") : "\u2013"}`, "live"]
  );
  C.Muted(Quality, "Render target after the scale and the pixel ceiling of the quality grade; ReSTIR GI and reflections trace at the trace resolution.");
  C.Segmented(Quality, S, "Quality", [["Low", 0], ["Medium", 1], ["High", 2]], { Label: "Quality grade \xB7 reloads" });
  C.Segmented(Quality, S, "TraceScale", [["Full", 1], ["Half", 2], ["Quarter", 4]], { Label: "Trace resolution" });
  Slider(C, Quality, S, "RenderScale", "Render scale", 0.25, 2, 0.05, "\xD7", 2, ["Faster", "Sharper"]);
  const Gather = C.Card(Body2, "Global illumination \xB7 ReSTIR", "Sparkles", { Accent: Accent.Render, Index: 4 });
  C.Switch(Gather, S, "TemporalReuse", { Label: "Temporal reuse", Detail: "Reservoirs carried through motion vectors" });
  C.Switch(Gather, S, "SpatialReuse", { Label: "Spatial reuse", Detail: "Neighbouring reservoirs merged per pixel" });
  C.Switch(Gather, S, "VisibilityReuse", { Label: "Visibility validation", Detail: "Reused samples re-traced for occlusion" });
  C.Switch(Gather, S, "RadianceRefresh", { Label: "Refresh reused radiance" });
  Slider(C, Gather, S, "SpatialCount", "Spatial candidates", 0, 8, 1, "", 0);
  Slider(C, Gather, S, "SpatialRadius", "Spatial radius", 2, 48, 1, "px", 0);
  Slider(C, Gather, S, "TemporalTallyLimit", "Temporal M limit", 1, 40, 1, "", 0, ["Responsive", "Stable"]);
  Slider(C, Gather, S, "IndirectScale", "Indirect intensity", 0, 3, 0.05, "\xD7", 2);
  const Image2 = C.Card(Body2, "Exposure & image", "Aperture", { Accent: Accent.Render, Index: 5 });
  C.Switch(Image2, S, "AutoExposure", { Label: "Auto exposure" });
  Slider(C, Image2, S, "ExposureCompensation", "Exposure compensation", -4, 4, 0.1, "EV", 1, ["Darker", "Brighter"]);
  C.Switch(Image2, S, "DirectShadow", { Label: "Sun shadows", Detail: "Ray-traced BVH cone or cascaded shadow depth" });
  C.Switch(Image2, S, "Reflection", { Label: "Glossy reflections", Detail: "BVH ray-traced or SDF-traced, SVGF denoised" });
  C.Switch(Image2, S, "VarianceKernel", { Label: "Denoiser (SVGF)" });
  C.Switch(Image2, S, "Antialias", { Label: "Temporal antialiasing", Detail: "Also resolves dithered tyre marks" });
  const Debug = C.Card(Body2, "Debug views", "Bug", { Accent: Accent.Render, Index: 6 });
  C.Select(Debug, S, "Inspection", InspectionModes, { Label: "Display" });
  C.Select(Debug, S, "DistanceInspection", DistanceInspections, { Label: "BVH / SDF view" });
  C.Switch(Debug, S, "HudVisible", { Label: "Readout overlay", Detail: "H" });
  C.Switch(Debug, S, "InsetEnabled", { Label: "Distance slice inset", Detail: "J" });
  Slider(C, Debug, S, "SliceHeight", "Slice height", 0.05, 4, 0.05, "m", 2);
  const Timing = C.Card(Body2, "Frame timing", "Activity", { Accent: Accent.Render, Index: 7 });
  C.Metric(Timing, () => 1 / Math.max(Host2.FrameSeconds || 1, 1e-4), "fps", 0, () => [`1% low ${Host2.LowRate || "\u2013"}`, ""]);
  C.Stats(Timing, [
    ["Frame", () => (Host2.FrameSeconds || 0) * 1e3, "ms", 1],
    ["Draw runs", () => Host2.Scene.DrawRuns.length],
    ["TLAS instances", () => Host2.RayTracing ? Host2.RayTracing.ActiveInstances : 0]
  ]);
  C.Readout(Timing, () => {
    if (!Host2.Metrics.Enabled)
      return ["GPU pass timings need the timestamp-query feature;", "this adapter does not expose it."];
    return Object.entries(Host2.Metrics.Durations).filter(([, Milliseconds]) => Milliseconds > 0).map(([Name, Milliseconds]) => `${Name.padEnd(24)}${Milliseconds.toFixed(2).padStart(7)} ms`);
  });
}
function BuildField(Host2, C, Body2) {
  const S = Host2.Settings;
  if (Host2.RayTracing) {
    const Bvh = C.Card(Body2, "Two-Level BVH (TLAS + BLAS)", "Zap", { Accent: Accent.Render, Index: 1 });
    C.Metric(
      Bvh,
      () => Host2.RayTracing.ActiveInstances,
      "instances",
      0,
      () => [`${Host2.RayTracing.TotalTriangles} triangles`, S.RayTracing ? "live" : "warm"]
    );
    C.Stats(Bvh, [
      ["TLAS nodes", () => Host2.RayTracing.UsedTlasNodes],
      ["BLAS nodes", () => Math.max(0, Host2.RayTracing.StaticNodeCount - 4608)],
      ["Triangles", () => Host2.RayTracing.TotalTriangles]
    ]);
    C.Muted(Bvh, "TLAS is rebuilt over active occupants each frame; per-mesh Binned-SAH BLAS hierarchies are built at bring-up and extended dynamically on fracture.");
  }
  const Field = C.Card(Body2, "Cascades", "GridLattice", { Accent: Accent.Render, Index: 2 });
  C.Metric(Field, () => Host2.Distance.TotalBricks, "bricks", 0, () => [S.FreezeDistance ? "frozen" : "updating", S.FreezeDistance ? "warm" : "live"]);
  C.Muted(Field, "Bricks rewritten since start: scrolling windows and moving occupants only.");
  C.Switch(Field, S, "FreezeDistance", { Label: "Freeze field updates" });
  C.Select(Field, S, "DistanceInspection", DistanceInspections, { Label: "Field view (display: global distance field)" });
  C.Switch(Field, S, "InsetEnabled", { Label: "Distance slice inset" });
  Slider(C, Field, S, "SliceHeight", "Slice height", 0.05, 4, 0.05, "m", 2);
  C.Readout(Field, () => Host2.QueryFieldLines());
}
function BuildCards(Host2, C, Body2) {
  const S = Host2.Settings;
  const Cards = C.Card(Body2, "Surface cache", "LayoutGrid", { Accent: Accent.Render, Index: 1 });
  C.Metric(Cards, () => Host2.Cards.ScheduledTiles, "tiles", 0, () => ["relit this frame", ""]);
  C.Switch(Cards, S, "CardRadiosity", { Label: "Card radiosity", Detail: "Multi-bounce inside the cache" });
  Slider(C, Cards, S, "CardTileBudget", "Static tiles per frame", 0, 8192, 64, "", 0, ["Lazy", "Eager"]);
  C.Readout(Cards, () => Host2.QueryDepotLines());
}
function BuildSun(Host2, C, Body2) {
  const S = Host2.Settings;
  const Preset = C.Card(Body2, "Lighting preset", "Sunrise", { Accent: Accent.Environment, Index: 1 });
  C.Segmented(
    Preset,
    S,
    "LightingPreset",
    Object.keys(LightingPresets).map((Name) => [Name, Name]),
    { OnChange: (Name) => Host2.ApplyPreset(Name) }
  );
  C.Muted(Preset, "Night drops the sun below the horizon: the lamps, the hangar strips and the tunnel light the course through the cards.");
  const Direction = C.Card(Body2, "Sun direction", "Orbit", { Accent: Accent.Environment, Index: 2 });
  C.Metric(Direction, () => S.SunElevation, "\xB0", 1, () => [S.SunElevation < 0 ? "below horizon" : "above horizon", S.SunElevation < 0 ? "warm" : "live"]);
  C.Instrument(Direction, 92, (Context, Width, Height) => DrawSunArc(Context, Width, Height, S.SunElevation, S.SunAzimuth), true);
  Slider(C, Direction, S, "SunElevation", "Elevation", -20, 85, 0.5, "\xB0", 1, ["Night", "Zenith"]);
  Slider(C, Direction, S, "SunAzimuth", "Azimuth", -180, 180, 1, "\xB0", 0);
  const Intensity = C.Card(Body2, "Light intensity", "Lightbulb", { Accent: Accent.Environment, Index: 3 });
  Slider(C, Intensity, S, "SolarIlluminance", "Solar intensity", 1, 30, 0.5, "", 1);
  Slider(C, Intensity, S, "SkyScale", "Sky intensity", 0, 3, 0.05, "\xD7", 2);
  Slider(C, Intensity, S, "EmissionScale", "Emitters (lamps, flames)", 0, 4, 0.05, "\xD7", 2);
  if (Host2.Lighting) {
    const Cluster = C.Card(Body2, "3D Clustered Lighting", "Sparkles", { Accent: Accent.Environment, Index: 4 });
    C.Metric(
      Cluster,
      () => Host2.Lighting.Lights.length,
      "active lights",
      0,
      () => [`${Host2.Lighting.ActiveClusterCells}/1024 cells`, Host2.Lighting.CullEnabled ? "live" : "warm"]
    );
    C.Stats(Cluster, [
      ["Point lights", () => Host2.Lighting.Lights.filter((L) => L.Type === 0).length],
      ["Street lamps", () => Host2.Lighting.Lights.filter((L) => L.Type === 1).length],
      ["Vehicle beams", () => Host2.Lighting.Lights.filter((L) => L.Type >= 2).length]
    ]);
    C.Muted(Cluster, "16\xD716\xD74 3D spatial grid with 64-bit per-cell light bitmasks and hardware firstTrailingBit traversal alongside emissive surface cards.");
    C.Switch(Cluster, Host2.Lighting, "CullEnabled", {
      Label: "3D cluster bitmask culling",
      Detail: "Skip out-of-range lights per 3D cell across Direct, Card & Path passes",
      OnChange: () => {
        Host2.Cards?.InvalidateLighting();
        Host2.PriorValid = false;
      }
    });
  }
}
function DrawSunArc(Context, Width, Height, Elevation, Azimuth) {
  const Horizon = Height * 0.78, Radius = Height * 0.62, Centre = Width * 0.5;
  Context.strokeStyle = "#3a3a3a";
  Context.lineWidth = 2;
  Context.beginPath();
  Context.moveTo(24, Horizon);
  Context.lineTo(Width - 24, Horizon);
  Context.stroke();
  Context.setLineDash([6, 8]);
  Context.beginPath();
  Context.arc(Centre, Horizon, Radius, Math.PI, 2 * Math.PI);
  Context.stroke();
  Context.setLineDash([]);
  const Angle = Math.PI - (Elevation + 20) / 105 * Math.PI;
  const X = Centre + Math.cos(Angle) * Radius, Y = Horizon - Math.sin(Angle) * Radius;
  const Glow = Context.createRadialGradient(X, Y, 2, X, Y, 34);
  Glow.addColorStop(0, Elevation > 0 ? "#ffe3a0" : "#9fb0d8");
  Glow.addColorStop(1, "rgba(0,0,0,0)");
  Context.fillStyle = Glow;
  Context.beginPath();
  Context.arc(X, Y, 34, 0, 2 * Math.PI);
  Context.fill();
  Context.fillStyle = Elevation > 0 ? "#ffd27a" : "#c3cff0";
  Context.beginPath();
  Context.arc(X, Y, 9, 0, 2 * Math.PI);
  Context.fill();
  Context.fillStyle = "#7d7d7d";
  Context.font = "20px DM Sans, sans-serif";
  Context.fillText(`azimuth ${Azimuth.toFixed(0)}\xB0`, 26, Height - 12);
}
