  C.Synchronise();
  C.Stats(Materials, [
    ["Crack resistance", () => Material().Gc, "J/m\xB2"],
    ["Density", () => Material().Density, "kg/m\xB3"],
    ["Prop mass", () => Prop.Mass, "kg"]
  ]);
  const Note = C.Muted(Materials, "");
  C.Live.push(() => {
    Note.textContent = Material().Note;
  });
  const Impact = C.Card(Body2, "Impact", "Zap", { Accent: Accent.Destruction, Index: 2 });
  C.Metric(Impact, () => BreakSpeed() * 3.6, "km/h to break", 0, () => [`${(Recipe.Threshold / 1e3).toFixed(1)} kJ`, ""]);
  C.Instrument(Impact, 96, (Context, Width, Height) => DrawBreakChart(Context, Width, Height, Reduced(), Recipe.Threshold), true);
  Slider(C, Impact, Recipe, "Threshold", "Break threshold", 100, 15e4, 100, "J", 0, ["Brittle", "Stops the car"]);
  Slider(C, Impact, Recipe, "Energy", "Baked impact energy", 200, 5e4, 100, "J", 0, null, () => {
    F.AssignRecipe(Prop, {});
    RedrawPreview();
  });
  Slider(C, Impact, Recipe, "Seed", "Pattern seed", 1, 9999, 1, "#", 0, null, () => {
    F.AssignRecipe(Prop, {});
    RedrawPreview();
  });
  C.Muted(Impact, "The impact point is wherever the car strikes (Dynamic) or the face it approaches from (Baked). Closer, larger pieces receive cut priority.");
  const Quality = C.Card(Body2, "Fragment quality", "Gem", { Accent: Accent.Destruction, Index: 3 });
  RedrawPreview = C.Instrument(Quality, 150, (Context, Width, Height) => DrawFragments(Context, Width, Height, Prop, Preview.Separation));
  Slider(C, Quality, Preview, "Separation", "Preview separation", 0, 1, 0.01, "", 2, null, () => RedrawPreview());
  Slider(C, Quality, Recipe, "Ceiling", "Fragment ceiling", 2, Prop.Definition.Capacity, 1, "pcs", 0, null, () => {
    F.AssignRecipe(Prop, {});
    RedrawPreview();
  });
  Slider(C, Quality, Recipe, "MinimumSize", "Minimum span", 0.01, 0.3, 5e-3, "m", 3, null, () => {
    F.AssignRecipe(Prop, {});
    RedrawPreview();
  });
  C.Pills(Quality, ["Needle rejection", "Closed caps", "Quality-aware triangulation"]);
  C.Muted(Quality, "Near-edge cuts and tiny pieces are refused. A limit is a ceiling \u2014 not a promise to force bad fragments.");
  const Bake = C.Card(Body2, "Bake", "Layers", { Accent: Accent.Destruction, Index: 4 });
  C.Segmented(
    Bake,
    Recipe,
    "Mode",
    [["Dynamic", FractureModes.Dynamic], ["Baked", FractureModes.Baked]],
    { OnChange: (Mode) => {
      F.AssignRecipe(Prop, { Mode });
      RedrawPreview();
    } }
  );
  const Explain = C.Muted(Bake, "");
  C.Live.push(() => {
    Explain.textContent = Recipe.Mode === FractureModes.Dynamic ? "Generate fragments on demand at the true impact point." : "Use the stored fragment geometry \u2014 no fracture generation at impact.";
  });
  const Actions = C.ActionRow(Bake);
  C.Button(Actions, "Bake geometry", "Layers", () => {
    F.BakeProp(Prop);
    RedrawPreview();
  }, "primary");
  C.Button(Actions, "Break now", "Hammer", () => F.BreakFromEditor(Prop));
  C.Button(Actions, "Reassemble", "Undo2", () => {
    if (Prop.State !== "intact") F.ReassembleProp(Prop);
  });
  const Receipt = C.Card(Body2, "Geometry receipt", "Scan", { Accent: Accent.Destruction, Index: 5 });
  C.Stats(Receipt, [
    ["Fragments", () => Prop.Receipt ? Prop.Receipt.Fragments : 0],
    ["Volume error", () => Prop.Receipt ? Prop.Receipt.VolumeError.toExponential(1) : "\u2013"],
    ["Min quality", () => Prop.Receipt ? Prop.Receipt.Quality : 0, "", 3]
  ]);
  C.Receipt(Receipt, [
    ["Triangles", () => Prop.Receipt ? Prop.Receipt.Triangles.toLocaleString("en-US") : "\u2013"],
    ["Refused candidates", () => Prop.Receipt ? Prop.Receipt.Rejected : "\u2013"],
    ["Energy spent", () => Prop.Receipt ? `${Prop.Receipt.Spent.toFixed(0)} / ${Prop.Receipt.Budget.toFixed(0)} J` : "\u2013"],
    ["Generation", () => Prop.Receipt ? `${Prop.Receipt.Milliseconds.toFixed(1)} ms` : "\u2013"],
    ["Topology", () => Prop.Receipt && Prop.Receipt.Closed ? "Closed" : "Open"],
    ["State", () => Prop.State]
  ]);
