function DrawBreakChart(Context, Width, Height, Reduced, Threshold) {
  const Left = 18, Right = Width - 18, Top = 16, Bottom = Height - 28;
  const MaximumSpeed = Math.max(4, Math.min(30, 2.2 * Math.sqrt(2 * Threshold / Reduced)));
  const MaximumEnergy = 0.5 * Reduced * MaximumSpeed * MaximumSpeed;
  const Point = (Speed2, Energy) => [Left + (Right - Left) * Speed2 / MaximumSpeed, Bottom - (Bottom - Top) * Math.min(1, Energy / MaximumEnergy)];
  const Gradient = Context.createLinearGradient(0, Top, 0, Bottom);
  Gradient.addColorStop(0, "rgba(143,179,164,0.45)");
  Gradient.addColorStop(1, "rgba(143,179,164,0.02)");
  Context.beginPath();
  Context.moveTo(Left, Bottom);
  for (let Step2 = 0; Step2 <= 80; ++Step2) {
    const Speed2 = MaximumSpeed * Step2 / 80;
    const [X, Y] = Point(Speed2, 0.5 * Reduced * Speed2 * Speed2);
    Context.lineTo(X, Y);
  }
  Context.lineTo(Right, Bottom);
  Context.closePath();
  Context.fillStyle = Gradient;
  Context.fill();
  Context.strokeStyle = "#8fb3a4";
  Context.lineWidth = 3;
  Context.beginPath();
  for (let Step2 = 0; Step2 <= 80; ++Step2) {
    const Speed2 = MaximumSpeed * Step2 / 80;
    const [X, Y] = Point(Speed2, 0.5 * Reduced * Speed2 * Speed2);
    if (Step2 === 0) Context.moveTo(X, Y);
    else Context.lineTo(X, Y);
  }
  Context.stroke();
  const [, Line] = Point(0, Threshold);
  Context.strokeStyle = "#e0a24a";
  Context.setLineDash([8, 8]);
  Context.lineWidth = 2;
  Context.beginPath();
  Context.moveTo(Left, Line);
  Context.lineTo(Right, Line);
  Context.stroke();
  Context.setLineDash([]);
  const Speed = Math.sqrt(2 * Threshold / Reduced);
  if (Speed < MaximumSpeed) {
    const [X, Y] = Point(Speed, Threshold);
    Context.fillStyle = "#f3f3f3";
    Context.beginPath();
    Context.arc(X, Y, 7, 0, 2 * Math.PI);
    Context.fill();
  }
  Context.fillStyle = "#7d7d7d";
  Context.font = "18px DM Sans, sans-serif";
  Context.fillText("impact speed \u2192", Right - 140, Height - 6);
  Context.fillStyle = "#e0a24a";
  Context.fillText("threshold", Left + 4, Line - 8);
}
function DrawFragments(Context, Width, Height, Prop, Separation) {
  const Fragments = Prop.Baked ? Prop.Baked.Fragments : [];
  const Material = FractureMaterials[Prop.Recipe.Material];
  const Yaw = 0.72, Pitch = 0.42;
  const Rotate = (P) => {
    const X = P[0] * Math.cos(Yaw) - P[1] * Math.sin(Yaw), Y = P[0] * Math.sin(Yaw) + P[1] * Math.cos(Yaw);
    return [X, Y * Math.cos(Pitch) - P[2] * Math.sin(Pitch), Y * Math.sin(Pitch) + P[2] * Math.cos(Pitch)];
  };
  const Triangles = [];
  let Reach = 0.01;
  for (const Fragment of Fragments) {
    const Offset = Fragment.Centroid.map((Component) => Component * (1 + 2.2 * Separation));
    for (const Triangle2 of Fragment.Triangles) {
      const Corners = Triangle2.Corners.map((Corner) => Rotate([Corner[0] + Offset[0], Corner[1] + Offset[1], Corner[2] + Offset[2]]));
      for (const Corner of Corners)
        Reach = Math.max(Reach, Math.abs(Corner[0]), Math.abs(Corner[2]));
      const U = [Corners[1][0] - Corners[0][0], Corners[1][1] - Corners[0][1], Corners[1][2] - Corners[0][2]];
      const V = [Corners[2][0] - Corners[0][0], Corners[2][1] - Corners[0][1], Corners[2][2] - Corners[0][2]];
      const Normal = [U[1] * V[2] - U[2] * V[1], U[2] * V[0] - U[0] * V[2], U[0] * V[1] - U[1] * V[0]];
      const Length2 = Math.hypot(...Normal) || 1;
      if (Normal[1] / Length2 > 0.02)
        continue;
      const Light = Math.max(0, (-0.35 * Normal[0] - 0.55 * Normal[1] + 0.76 * Normal[2]) / Length2);
      Triangles.push({ Corners, Depth: (Corners[0][1] + Corners[1][1] + Corners[2][1]) / 3, Light, Interior: Triangle2.Family === Material.Interior });
    }
  }
  Triangles.sort((First, Second) => Second.Depth - First.Depth);
  const Scale3 = Math.min(Width, Height) * 0.42 / Reach;
  const Skin2 = HexToRgb(Material.Colour), Inside = HexToRgb(Material.InteriorColour);
  for (const Triangle2 of Triangles) {
    const Base = Triangle2.Interior ? Inside : Skin2;
    const Shade = 0.32 + 0.68 * Triangle2.Light;
    Context.fillStyle = `rgb(${Base.map((Channel) => Math.round(Channel * Shade)).join(",")})`;
    Context.strokeStyle = "rgba(10,10,10,0.55)";
    Context.lineWidth = 1;
    Context.beginPath();
    Triangle2.Corners.forEach((Corner, Index) => {
      const X = Width * 0.5 + Corner[0] * Scale3, Y = Height * 0.53 - Corner[2] * Scale3;
      if (Index === 0) Context.moveTo(X, Y);
      else Context.lineTo(X, Y);
    });
    Context.closePath();
    Context.fill();
    Context.stroke();
  }
  Context.fillStyle = "#7d7d7d";
  Context.font = "18px DM Sans, sans-serif";
  Context.fillText(`${Fragments.length} fragments \xB7 ${Prop.Recipe.Mode}`, 18, Height - 12);
}
function HexToRgb(Hex) {
  const Value = parseInt(Hex.slice(1), 16);
  return [Value >> 16 & 255, Value >> 8 & 255, Value & 255];
}
