      Burning,
      Strength: 1.6,
      Position: Burning ? [Point[0], Point[1], 0.25] : Point,
      Hub: [Point[0], Point[1], 0.35],
      Radius: Burning ? 0.45 : 0.35,
      Expansion: Burning ? 5 : 0.6,
      SmokeRate: Burning ? 0 : 26,
      SootRate: 0,
      FlameRate: Burning ? 12 : 0,
      HeatRate: Burning ? 39 : 1.2,
